changeSet.sql:
INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Belgique – Parlements des entités fédérées (PFWB, PDG, Bruxelles)', 'Membres et présidents du Parlement de la Fédération Wallonie-Bruxelles, du Parlement de la Communauté germanophone et du Parlement bruxellois (catégorie BE-b)', 'be_pep_regional_parliaments', 'PEP', 'https://www.pfwb.be/les-94-deputes', 'be-pep-regional-parliaments', 'D:/test parser 2/plugins/swiftcheck-aml-be-pep-regional-parliaments-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'WEB_PAGE', NULL, '{"pfwb": "https://www.pfwb.be/les-94-deputes", "pdgMembers": "https://pdg.be/desktopdefault.aspx/tabid-4065/", "pdgBureau": "https://pdg.be/desktopdefault.aspx/tabid-4014/"}', 168, 12, 'Citer la source (PFWB, PDG, Parlement bruxellois)', 'Parlement de la Fédération Wallonie-Bruxelles (pfwb.be) ; Parlament der Deutschsprachigen Gemeinschaft (pdg.be)', 'Couvre les 94 députés du PFWB et les 25 membres (et Präsidium) du Parlement de la Communauté germanophone. Les parlements flamand et wallon sont couverts par des parsers dédiés au lot 1.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Les 94 députés du Parlement de la Fédération Wallonie-Bruxelles, avec groupe politique, fonction au bureau ou en commission et portrait officiel.', 'Pas de date de naissance sur la liste publique.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'BE-b' AND f.label LIKE 'Membre du Parlement de la Fédération Wallonie-Bruxelles%' AND p.dataset_name = 'be_pep_regional_parliaments';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Les 25 membres du Parlement de la Communauté germanophone et les membres de son Präsidium, avec groupe politique et portrait officiel.', 'Pas de date de naissance sur la liste publique.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'BE-b' AND f.label LIKE 'Membre du Parlement de la Communauté germanophone%' AND p.dataset_name = 'be_pep_regional_parliaments';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', FALSE, 'Les 19 députés francophones bruxellois siégeant au Parlement de la Fédération Wallonie-Bruxelles.', 'Le site parlement.brussels ne répond pas aux requêtes automatiques (timeout).' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'BE-b' AND f.label LIKE 'Membre du Parlement de la Région de Bruxelles-Capitale%' AND p.dataset_name = 'be_pep_regional_parliaments';

UPDATE parser SET website_url = 'https://www.senate.be/www/?MIval=/WieIsWie/LijstDerSenatoren&LANG=fr', data_source_type = 'PLUGIN_MANAGED', source_location = NULL, parameters = '{"url": "https://www.senate.be/www/?MIval=/WieIsWie/LijstDerSenatoren&LANG=fr"}' WHERE dataset_name = 'be_pep_senate';
