UPDATE parser SET website_url = 'https://www.raadvst-consetat.be/fr/le-conseil-detat/organisation/direction-et-gestion/', data_source_type = 'PLUGIN_MANAGED', source_location = NULL, parameters = '{"url": "https://www.raadvst-consetat.be/fr/le-conseil-detat/organisation/direction-et-gestion/"}' WHERE dataset_name = 'be_pep_council_of_state';
