UPDATE parser SET website_url = 'https://www.nbb.be/fr/la-banque-nationale/administration-et-controle/organes-de-la-banque/comite-de-direction', data_source_type = 'PLUGIN_MANAGED', source_location = NULL, parameters = '{"comiteDirectionUrl": "https://www.nbb.be/fr/la-banque-nationale/administration-et-controle/organes-de-la-banque/comite-de-direction", "conseilRegenceUrl": "https://www.nbb.be/fr/la-banque-nationale/administration-et-controle/organes-de-la-banque/conseil-de-regence"}' WHERE dataset_name = 'be_pep_national_bank';
